SELECT id, account_id, topics, purpose, experience, languages, time_commitment,
       custom_topics, custom_purpose, custom_exp, custom_lang, custom_time, use_rag, use_persona,
       prefer_beginner_projects, prefer_career_projects,
       result_json, create_time
FROM trend_history WHERE account_id = #{accountId}
ORDER BY id DESC LIMIT #{limit}
